function Logo() { return <div className="flex items-center gap-2.5"><div className="brand-mark"><span /><span /><span /></div><span className="text-[15px] font-extrabold tracking-[-.04em] text-white">ShikshaSetu</span></div>; }
function Button({ children, onClick, variant = "primary", className = "" }: { children: React.ReactNode; onClick?: () => void; variant?: "primary" | "outline" | "ghost"; className?: string }) { return <button onClick={onClick} className={`inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2.5 text-[11px] font-bold transition active:scale-[.98] ${variant === "primary" ? "bg-[#efede8] text-[#0a0a0b] hover:bg-white" : variant === "outline" ? "border border-white/12 bg-white/[.035] text-white hover:bg-white/[.08]" : "text-white/55 hover:bg-white/[.06] hover:text-white"} ${className}`}>{children}</button>; }
function SectionTitle({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle?: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="eyebrow">{eyebrow}</div><h1 className="mt-3 text-3xl font-bold tracking-[-.065em] text-white md:text-4xl">{title}</h1>{subtitle && <p className="mt-2 max-w-2xl text-sm leading-6 text-white/40">{subtitle}</p>}</div>{action}</div>; }
function Glass({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <div className={`glass-surface rounded-xl ${className}`}>{children}</div>; }
function Progress({ value, color = "bg-[#a890dc]" }: { value: number; color?: string }) { return <div className="h-1.5 overflow-hidden rounded-full bg-white/[.08]"><div className={`h-full rounded-full ${color}`} style={{ width: `${value}%` }} /></div>; }
function Status({ children, tone = "neutral" }: { children: React.ReactNode; tone?: "green" | "violet" | "amber" | "red" | "neutral" }) { const styles = { green: "bg-[#8eaa95]/15 text-[#abd0b0]", violet: "bg-[#a28ad6]/15 text-[#c1aeeb]", amber: "bg-[#b29363]/15 text-[#d8ba84]", red: "bg-[#b46e6e]/15 text-[#dc9b9b]", neutral: "bg-white/[.08] text-white/45" }; return <span className={`rounded-md px-2 py-1 text-[9px] font-mono uppercase tracking-wider ${styles[tone]}`}>{children}</span>; }

function WorkspaceShell({ role, page, children, onCommand }: { role: Role; page: Page; children: React.ReactNode; onCommand: () => void }) {
  const navigate = useNavigate(); const meta = roleMeta[role]; const roleNav = navByRole[role]; const Icon = meta.icon;
  const switchRole = (next: Role) => navigate(`/app/${next}/${navByRole[next][0].slug}`);
  return <div className="min-h-screen bg-[#080809] text-[#f2f0ed]"><aside className="fixed inset-y-0 left-0 z-30 hidden w-[234px] flex-col border-r border-white/10 bg-[#0b0b0d]/95 px-4 py-5 backdrop-blur-xl lg:flex"><Logo /><div className="mt-8 rounded-lg border border-white/10 bg-white/[.025] p-1"><div className="px-2 py-1 text-[9px] font-mono uppercase tracking-[.18em] text-white/30">Demo perspective</div>{(Object.keys(roleMeta) as Role[]).map(r => <button key={r} onClick={() => switchRole(r)} className={`flex w-full items-center justify-between rounded-md px-2 py-2 text-[11px] font-semibold transition ${role === r ? "bg-white/10 text-white" : "text-white/40 hover:text-white"}`}>{roleMeta[r].label}{role === r && <span className="h-1.5 w-1.5 rounded-full bg-[#b69ce7]" />}</button>)}</div><div className="mt-7 flex-1 space-y-1 overflow-y-auto pr-1">{roleNav.map(item => { const NavIcon = item.icon; const active = item.slug === page; return <button key={item.slug} onClick={() => navigate(`/app/${role}/${item.slug}`)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-[11px] font-semibold transition ${active ? "bg-[#9b7dcc]/15 text-white" : "text-white/40 hover:bg-white/[.045] hover:text-white"}`}><NavIcon size={15} />{item.label}{item.slug === "roadmap" && <span className="ml-auto text-[9px] text-[#bba4e8]">LIVE</span>}</button>; })}</div><div className="mt-auto space-y-1 border-t border-white/10 pt-4"><button className="flex w-full items-center gap-3 px-3 py-2 text-[11px] text-white/40"><CircleHelp size={15} />Help center</button><button className="flex w-full items-center gap-3 px-3 py-2 text-[11px] text-white/40"><PanelLeft size={15} />Preferences</button><div className="mt-3 flex items-center gap-2 rounded-lg bg-white/[.04] p-2"><div className="flex h-7 w-7 items-center justify-center rounded-full bg-[#d5c6ed] text-[10px] font-bold text-[#17121e]">{role === "student" ? "AS" : role === "faculty" ? "KR" : role === "industry" ? "NS" : "SI"}</div><div className="min-w-0"><div className="truncate text-[10px] font-bold text-white">{meta.name}</div><div className="text-[9px] text-white/35">{meta.subtitle}</div></div></div></div></aside><div className="lg:pl-[234px]"><header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-white/10 bg-[#080809]/88 px-5 backdrop-blur-xl md:px-8"><div className="flex items-center gap-3 lg:hidden"><Logo /></div><div className="hidden text-[11px] text-white/35 lg:block"><span className="text-white/75">{meta.label} workspace</span><span className="mx-2">/</span>{page.replace(/-/g, " ")}</div><button onClick={onCommand} className="ml-auto flex w-full max-w-[340px] items-center gap-3 rounded-lg border border-white/10 bg-white/[.035] px-3 py-2 text-[11px] text-white/35 hover:border-white/20 md:ml-0"><Search size={14} /><span>Search skills, roles, opportunities...</span><span className="ml-auto hidden items-center gap-1 rounded border border-white/10 px-1.5 py-0.5 font-mono text-[9px] text-white/35 sm:flex"><Command size={10} />K</span></button><div className="ml-4 hidden items-center gap-4 sm:flex"><Bell size={16} className="text-white/45" /><div className="h-7 w-7 rounded-full bg-[#d5c6ed] text-center text-[10px] font-bold leading-7 text-[#17121e]">{role === "student" ? "AS" : role === "faculty" ? "KR" : role === "industry" ? "NS" : "SI"}</div></div></header><main className="mx-auto max-w-[1450px] px-5 py-8 md:px-8 md:py-10">{children}</main></div></div>;
}

function CommandPalette({ onClose }: { onClose: () => void }) { return <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/70 px-4 pt-[16vh] backdrop-blur-sm" onClick={onClose}><div className="w-full max-w-[600px] rounded-xl border border-white/15 bg-[#141416] p-3 shadow-2xl" onClick={e => e.stopPropagation()}><div className="flex items-center gap-3 border-b border-white/10 px-3 pb-3"><Search size={17} className="text-white/35" /><input autoFocus placeholder="Search skills, roles, opportunities..." className="w-full bg-transparent text-sm text-white outline-none placeholder:text-white/30" /><span className="font-mono text-[10px] text-white/30">ESC</span></div><div className="py-3"><div className="px-3 pb-2 text-[9px] font-mono uppercase tracking-widest text-white/30">Global intelligence</div>{[["Docker","Skill · 12 courses · 219 opportunities",Fingerprint],["AI / ML Engineer","Role · 1,284 candidates ready",BriefcaseBusiness],["MLOps","Critical gap · 4 interventions",Network]].map(([a, b, I]) => { const Icon = I as typeof Network; return <button key={a as string} className="flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left hover:bg-white/[.07]"><Icon size={15} className="text-[#b69de5]" /><span><span className="block text-xs font-semibold text-white">{a as string}</span><span className="block text-[10px] text-white/35">{b as string}</span></span><ArrowRight size={13} className="ml-auto text-white/25" /></button>; })}</div></div></div>; }

function StudentOverview({ go }: { go: (page: string) => void }) { return <><SectionTitle eyebrow="Student / overview" title="Good evening, Aanya." subtitle="You're closer than you think. Here's the signal for today." action={<div className="flex gap-2"><Status tone="green">● System healthy</Status><Button variant="outline" onClick={() => go("skill-dna")}>Build Skill DNA <ArrowRight size={13} /></Button></div>} /><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"> <Glass className="overflow-hidden p-0"><div className="border-b border-white/10 p-5 md:p-7"><div className="flex items-start justify-between"><div><div className="eyebrow">Career signal / 2027</div><h2 className="mt-3 text-2xl font-bold tracking-[-.06em] text-white">AI / ML Engineer</h2><p className="mt-2 text-xs text-white/40">Your current evidence maps to 47 active opportunities.</p></div><div className="text-right"><div className="text-4xl font-bold tracking-[-.08em] text-[#bba5e8]">72%</div><div className="mt-1 text-[10px] text-white/35">skill readiness</div></div></div><div className="mt-7 grid gap-4 sm:grid-cols-3"><div><div className="text-[10px] text-white/35">Verified skills</div><div className="mt-2 font-mono text-xl text-white">18</div></div><div><div className="text-[10px] text-white/35">Evidence confidence</div><div className="mt-2 font-mono text-xl text-white">81%</div></div><div><div className="text-[10px] text-white/35">This month</div><div className="mt-2 font-mono text-xl text-[#a9c9ad]">+12%</div></div></div></div><div className="p-5 md:p-7"><div className="flex items-center justify-between"><div><div className="eyebrow">Signal map</div><h3 className="mt-2 font-bold text-white">Your pathway has one critical gap.</h3></div><button onClick={() => go("roadmap")} className="text-[10px] text-white/45 hover:text-white">Open roadmap <ArrowRight size={12} className="ml-1 inline" /></button></div><div className="mt-6 flex items-center gap-2 overflow-x-auto pb-2">{["AI / ML Engineer", "Machine Learning", "Docker", "Production API", "Industry mission", "Internship"].map((n, i) => <div key={n} className="flex shrink-0 items-center gap-2"><div className={`rounded-lg border px-3 py-3 ${i === 2 ? "border-[#b294e2]/50 bg-[#a58cda]/10" : i < 2 ? "border-[#8eaa95]/35 bg-[#8eaa95]/10" : "border-white/10 bg-white/[.035]"}`}><div className="text-[10px] font-bold text-white">{n}</div><div className="mt-1 text-[9px] text-white/40">{i === 2 ? "31% / 75%" : i < 2 ? "verified" : "locked"}</div></div>{i < 5 && <ArrowRight className="shrink-0 text-white/20" size={13} />}</div>)}</div></div></Glass><div className="space-y-5"><Glass className="p-5"><div className="eyebrow">Next best action</div><h3 className="mt-3 text-lg font-bold text-white">Close your Docker gap</h3><p className="mt-2 text-xs leading-5 text-white/40">One project can move your readiness from 72% to an estimated 79%.</p><Button className="mt-5 w-full" onClick={() => go("missions")}>Deploy an ML API <ArrowRight size={13} /></Button></Glass><Glass className="p-5"><div className="flex items-center justify-between"><div className="eyebrow">Recent evidence</div><button onClick={() => go("skill-dna")} className="text-[10px] text-white/35">View all</button></div><div className="mt-4 space-y-3">{[["Python assessment","+8 confidence","green"],["Fraud detection project","+1 evidence","violet"],["Mentor validation","Awaiting review","amber"]].map(([a, b, tone]) => <div key={a} className="flex items-center gap-3"><div className={`h-2 w-2 rounded-full ${tone === "green" ? "bg-[#8faf98]" : tone === "violet" ? "bg-[#a790db]" : "bg-[#c3a064]"}`} /><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold text-white/75">{a}</div><div className="text-[10px] text-white/35">{b}</div></div><ChevronRight size={13} className="text-white/25" /></div>)}</div></Glass></div></div></>; }

function SkillDNA() { const [selected, setSelected] = useState(studentSkills[3]); return <><SectionTitle eyebrow="Student / intelligence" title="Skill DNA" subtitle="A living representation of what you can do, how we know it, and what the market needs next." action={<Button variant="outline"><Fingerprint size={14} /> Export evidence</Button>} /><div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Glass className="overflow-hidden p-0"><div className="flex flex-col justify-between gap-4 border-b border-white/10 p-5 md:flex-row md:items-center md:p-7"><div><div className="eyebrow">Aanya Sharma / 18 verified skills</div><h2 className="mt-2 text-xl font-bold tracking-[-.04em] text-white">Capability map</h2></div><div className="flex gap-2"><Status tone="green">12 verified</Status><Status tone="red">2 critical gaps</Status></div></div><div className="border-b border-white/10 p-5 md:p-7"><div className="mb-3 grid grid-cols-[1.4fr_.6fr_.5fr_.5fr] gap-4 text-[9px] font-mono uppercase tracking-widest text-white/30"><span>Skill / category</span><span>Proficiency</span><span>Confidence</span><span>Evidence</span></div><div className="space-y-1">{studentSkills.map(skill => <button key={skill.name} onClick={() => setSelected(skill)} className={`grid w-full grid-cols-[1.4fr_.6fr_.5fr_.5fr] items-center gap-4 rounded-lg p-3 text-left transition ${selected.name === skill.name ? "bg-white/[.08]" : "hover:bg-white/[.04]"}`}><div className="min-w-0"><div className="flex items-center gap-2"><span className="truncate text-xs font-bold text-white">{skill.name}</span><span className="hidden text-[9px] text-white/30 sm:inline">{skill.category}</span></div><div className="mt-2 max-w-[150px]"><Progress value={skill.current} color={skill.state === "critical gap" ? "bg-[#bd9369]" : skill.state === "verified" ? "bg-[#8eaf98]" : "bg-[#a890dc]"} /></div></div><div><span className="font-mono text-sm text-white">{skill.current}%</span><span className="ml-1 text-[9px] text-white/30">/ {skill.required}</span></div><div className="font-mono text-xs text-white/60">{skill.confidence}%</div><div className="flex items-center gap-1 font-mono text-xs text-white/60"><FileText size={12} />{skill.evidence}</div></button>)}</div></div><div className="grid gap-4 p-5 md:grid-cols-3 md:p-7">{[["Verified signal","81%","across all evidence"],["Industry relevance","High","AI / ML segment"],["Evidence freshness","18 days","average recency"]].map(([a,b,c]) => <div key={a} className="border-l border-white/10 pl-3"><div className="text-[10px] text-white/35">{a}</div><div className="mt-2 font-mono text-lg text-white">{b}</div><div className="mt-1 text-[10px] text-white/30">{c}</div></div>)}</div></Glass><Glass className="p-5 md:p-6"><div className="eyebrow">Skill intelligence / selected</div><div className="mt-5 flex items-start justify-between"><div><h2 className="text-2xl font-bold tracking-[-.06em] text-white">{selected.name}</h2><div className="mt-1 text-xs text-white/40">{selected.category} · {selected.state}</div></div><Status tone={selected.state === "critical gap" ? "red" : selected.state === "verified" ? "green" : "violet"}>{selected.state}</Status></div><div className="mt-7 grid grid-cols-3 gap-2"><div className="rounded-lg border border-white/10 bg-white/[.03] p-3"><div className="text-[9px] text-white/35">Current</div><div className="mt-1 font-mono text-xl text-white">{selected.current}%</div></div><div className="rounded-lg border border-[#a58cda]/25 bg-[#a58cda]/10 p-3"><div className="text-[9px] text-white/45">Required</div><div className="mt-1 font-mono text-xl text-[#c4b1e8]">{selected.required}%</div></div><div className="rounded-lg border border-[#bd9369]/25 bg-[#bd9369]/10 p-3"><div className="text-[9px] text-white/45">Gap</div><div className="mt-1 font-mono text-xl text-[#d6b67f]">{Math.max(selected.required - selected.current, 0)}%</div></div></div><div className="mt-7 space-y-5 border-t border-white/10 pt-5"><div><div className="eyebrow">Why ShikshaSetu believes this</div><p className="mt-3 text-sm leading-6 text-white/55">Your confidence is based on <b className="text-white">{selected.evidence} evidence items</b>, weighted by verification quality and recency.</p></div><div><div className="eyebrow">Evidence trail</div><div className="mt-3 space-y-2">{["Assessment result", "Production ML API project", "Mentor validation"].slice(0, Math.max(1, Math.min(selected.evidence, 3))).map((e, i) => <div key={e} className="flex items-center gap-2 text-xs text-white/65"><Check size={13} className="text-[#9bc4a3]" />{e}<span className="ml-auto text-[10px] text-white/30">{i === 0 ? selected.recency : "verified"}</span></div>)}</div></div></div><Button className="mt-7 w-full">{selected.state === "verified" ? "Find related opportunities" : "Start next best action"} <ArrowRight size={13} /></Button></Glass></div></>; }

function nodeStyle(status: string) { return { border: status === "critical gap" ? "1px solid rgba(189,147,105,.65)" : status === "verified" ? "1px solid rgba(142,175,152,.5)" : "1px solid rgba(255,255,255,.15)", background: status === "critical gap" ? "#1c1711" : status === "verified" ? "#111b16" : "#141317", borderRadius: 10, color: "#f2f0ed", padding: 12, width: 180, boxShadow: status === "critical gap" ? "0 0 25px rgba(189,147,105,.13)" : "0 12px 30px rgba(0,0,0,.25)" }; }
function GraphNode({ data }: any) { return <div style={nodeStyle(data.status)}><Handle type="target" position={Position.Left} style={{ background: "#8e7cad", border: 0 }} /><div style={{ fontSize: 10, color: "rgba(255,255,255,.38)", textTransform: "uppercase", letterSpacing: ".14em", fontFamily: "DM Mono" }}>{data.type}</div><div style={{ fontSize: 12, fontWeight: 700, marginTop: 7 }}>{data.title}</div><div style={{ fontSize: 10, color: "rgba(255,255,255,.42)", marginTop: 4 }}>{data.meta}</div><Handle type="source" position={Position.Right} style={{ background: "#8e7cad", border: 0 }} /></div>; }
const graphNodes = [
  { id: "goal", type: "graph", position: { x: 20, y: 170 }, data: { type: "goal", title: "AI / ML Engineer", meta: "Target role", status: "verified" } },
  { id: "ml", type: "graph", position: { x: 280, y: 80 }, data: { type: "skill", title: "Machine Learning", meta: "72% · in progress", status: "in progress" } },
  { id: "docker", type: "graph", position: { x: 280, y: 260 }, data: { type: "skill", title: "Docker", meta: "31% / 75% required", status: "critical gap" } },
  { id: "project", type: "graph", position: { x: 550, y: 80 }, data: { type: "project", title: "Production ML API", meta: "3 weeks · intermediate", status: "recommended" } },
  { id: "mission", type: "graph", position: { x: 550, y: 260 }, data: { type: "mission", title: "RAG API mission", meta: "Industry challenge", status: "locked" } },
  { id: "role", type: "graph", position: { x: 820, y: 170 }, data: { type: "outcome", title: "Role ready", meta: "18 opportunities unlock", status: "locked" } },
];
const graphEdges = [{ id: "e1", source: "goal", target: "ml", animated: true }, { id: "e2", source: "goal", target: "docker", animated: true }, { id: "e3", source: "ml", target: "project" }, { id: "e4", source: "docker", target: "mission" }, { id: "e5", source: "project", target: "role" }, { id: "e6", source: "mission", target: "role" }];
function Roadmap() { const [nodes, , onNodesChange] = useNodesState(graphNodes); const [edges, , onEdgesChange] = useEdgesState(graphEdges); const [selected, setSelected] = useState<any>(graphNodes[2]); const [completed, setCompleted] = useState(false); const nodeTypes = useMemo(() => ({ graph: GraphNode }), []); return <><SectionTitle eyebrow="Student / spatial intelligence" title="Career roadmap" subtitle="A living skill graph generated from your goal, evidence and the role market." action={<div className="flex gap-2"><Button variant="outline"><Plus size={13} /> Add node</Button><Button>Generate roadmap <Sparkles size={13} /></Button></div>} /><div className="grid gap-5 xl:grid-cols-[1fr_330px]"><Glass className="overflow-hidden p-0"><div className="flex items-center justify-between border-b border-white/10 px-4 py-3"><div className="flex items-center gap-2 text-[10px] text-white/45"><span className="h-1.5 w-1.5 rounded-full bg-[#a58cda]" /> AI / ML Engineer <span className="text-white/20">·</span> 6 months</div><div className="flex items-center gap-3 text-[10px] text-white/30"><span>6 nodes</span><span>5 relationships</span></div></div><div className="h-[570px] bg-[#09090b]"><ReactFlow nodes={nodes} edges={edges} onNodesChange={onNodesChange} onEdgesChange={onEdgesChange} nodeTypes={nodeTypes} onNodeClick={(_, n) => setSelected(n)} fitView proOptions={{ hideAttribution: true }}><Background color="#28252d" gap={28} size={1} /><Controls showInteractive={false} /><MiniMap nodeColor={(n: any) => n.data.status === "critical gap" ? "#b88c61" : n.data.status === "verified" ? "#8caf98" : "#8a73b0"} maskColor="rgba(8,8,9,.78)" /></ReactFlow></div><div className="flex flex-wrap gap-4 border-t border-white/10 px-4 py-3 text-[9px] font-mono uppercase tracking-wider text-white/30"><span><i className="mr-1.5 inline-block h-1.5 w-1.5 rounded-full bg-[#8caf98]" />verified</span><span><i className="mr-1.5 inline-block h-1.5 w-1.5 rounded-full bg-[#a58cda]" />in progress</span><span><i className="mr-1.5 inline-block h-1.5 w-1.5 rounded-full bg-[#b88c61]" />critical gap</span><span><i className="mr-1.5 inline-block h-1.5 w-1.5 rounded-full bg-white/30" />locked</span></div></Glass><Glass className="p-5"><div className="eyebrow">Node intelligence</div><div className="mt-5"><Status tone={selected.data.status === "critical gap" ? "red" : selected.data.status === "verified" ? "green" : "violet"}>{selected.data.status}</Status><h2 className="mt-3 text-xl font-bold tracking-[-.04em] text-white">{selected.data.title}</h2><p className="mt-1 text-xs text-white/40">{selected.data.meta}</p></div>{selected.id === "docker" ? <><div className="mt-6 grid grid-cols-3 gap-2"><div className="rounded-lg border border-white/10 bg-white/[.035] p-3"><span className="text-[9px] text-white/35">Current</span><b className="mt-1 block font-mono text-lg">{completed ? "78%" : "31%"}</b></div><div className="rounded-lg border border-[#a58cda]/25 bg-[#a58cda]/10 p-3"><span className="text-[9px] text-white/45">Required</span><b className="mt-1 block font-mono text-lg text-[#c0abe9]">75%</b></div><div className="rounded-lg border border-[#bd9369]/25 bg-[#bd9369]/10 p-3"><span className="text-[9px] text-white/45">Gap</span><b className="mt-1 block font-mono text-lg text-[#d1ae76]">{completed ? "0%" : "44%"}</b></div></div><div className="mt-6 space-y-5 border-t border-white/10 pt-5"><div><div className="eyebrow">Why it matters</div><p className="mt-2 text-xs leading-5 text-white/55">Production deployment is one of the largest recurring gaps across your target role.</p></div><div><div className="eyebrow">Next action</div><p className="mt-2 text-xs leading-5 text-white/55">Deploy an ML API using Docker to generate verified evidence.</p></div><div><div className="eyebrow">Unlocks</div><p className="mt-2 font-mono text-xl text-white">18 <span className="text-xs text-white/35">opportunities</span></p></div></div><Button className="mt-6 w-full" onClick={() => setCompleted(true)}>{completed ? <><Check size={13} /> Mission completed</> : <>Complete simulated mission <ArrowRight size={13} /></>}</Button></> : <div className="mt-6 space-y-5 border-t border-white/10 pt-5"><p className="text-xs leading-5 text-white/50">This node is connected to {selected.id === "goal" ? "your role target and downstream evidence" : "your next pathway decision"}.</p><Button variant="outline" className="w-full">Inspect dependencies <ArrowRight size={13} /></Button></div>}</Glass></div></>; }

function CareerSimulator() { const [path, setPath] = useState([false, false, false, false]); const gains = [7, 9, 10, 8]; const projected = 54 + path.reduce((a, v, i) => a + (v ? gains[i] : 0), 0); return <><SectionTitle eyebrow="Student / decision intelligence" title="Career simulator" subtitle="Compare intervention paths before you commit your time. Every number is a model estimate, not a guarantee." action={<Status tone="violet">Model estimate</Status>} /><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Glass className="p-6"><div className="eyebrow">Target role</div><div className="mt-3 flex items-center justify-between"><h2 className="text-2xl font-bold tracking-[-.05em] text-white">AI / ML Engineer</h2><ChevronDown size={17} className="text-white/35" /></div><div className="mt-8 grid grid-cols-2 gap-3"><div className="rounded-lg border border-white/10 bg-white/[.035] p-4"><div className="text-[10px] text-white/35">Current readiness</div><div className="mt-2 font-mono text-3xl text-white">54%</div></div><div className="rounded-lg border border-[#a58cda]/30 bg-[#a58cda]/10 p-4"><div className="text-[10px] text-white/45">Projected</div><div className="mt-2 font-mono text-3xl text-[#c0aae8]">{projected}%</div></div></div><div className="mt-7"><div className="mb-2 flex justify-between text-[10px] text-white/35"><span>Readiness trajectory</span><span>85% required</span></div><div className="relative h-2 rounded-full bg-white/[.08]"><div className="absolute inset-y-0 left-0 rounded-full bg-[#a58cda] transition-all" style={{ width: `${projected}%` }} /><div className="absolute -top-1.5 h-5 border-l border-dashed border-white/50" style={{ left: "85%" }} /></div></div><div className="mt-8 flex items-center justify-between border-t border-white/10 pt-5"><div><div className="text-[10px] text-white/35">Eligible opportunities</div><div className="mt-1 font-mono text-xl text-white">{127 + (projected - 54) * 3}</div></div><div className="text-right"><div className="text-[10px] text-white/35">Potential increase</div><div className="mt-1 font-mono text-xl text-[#a9c9ad]">+{(projected - 54) * 3}</div></div></div></Glass><Glass className="p-6"><div className="eyebrow">Compare intervention paths</div><div className="mt-5 space-y-2">{[["Complete Docker mission","Deploy a production ML API","+7%"],["Complete AWS pathway","Cloud fundamentals + labs","+9%"],["Complete MLOps assessment","Operationalize model lifecycle","+10%"],["Build production project","Portfolio-grade evidence","+8%"]].map(([a,b,g], i) => <button onClick={() => setPath(p => p.map((v, j) => j === i ? !v : v))} key={a} className={`flex w-full items-center gap-3 rounded-lg border p-4 text-left transition ${path[i] ? "border-[#a58cda]/45 bg-[#a58cda]/10" : "border-white/10 bg-white/[.025] hover:bg-white/[.06]"}`}><div className={`flex h-5 w-5 items-center justify-center rounded border ${path[i] ? "border-[#a58cda] bg-[#a58cda] text-black" : "border-white/20"}`}>{path[i] && <Check size={12} />}</div><div className="min-w-0 flex-1"><div className="text-xs font-bold text-white">{a}</div><div className="mt-1 text-[10px] text-white/35">{b}</div></div><span className="font-mono text-xs text-[#bda6e8]">{g}</span></button>)}</div><div className="mt-6 flex items-center justify-between rounded-lg border border-white/10 bg-white/[.025] p-4"><div><div className="text-xs font-bold text-white">Simulate this pathway</div><div className="mt-1 text-[10px] text-white/35">Compare evidence and opportunity impact.</div></div><Button onClick={() => setPath([true, true, true, true])}>Simulate <Zap size={13} /></Button></div></Glass></div></>; }

function InstitutionCommand({ go }: { go: (p: string) => void }) { const [filter, setFilter] = useState("All departments"); const rows = [["MLOps", "CSE", "34%", "81%", "critical"], ["Generative AI", "CSE", "42%", "94%", "critical"], ["Cloud Computing", "IT", "51%", "88%", "high"], ["Cybersecurity", "ECE", "63%", "79%", "medium"], ["Data Engineering", "CSE", "68%", "84%", "medium"]]; return <><SectionTitle eyebrow="Institution / command center" title="Understand what students will need." subtitle="ShikshaSetu Institute of Technology · before placement season." action={<div className="flex gap-2"><Button variant="outline"><FileText size={13} /> Export report</Button><Button onClick={() => go("simulator")}>What-if simulator <ArrowRight size={13} /></Button></div>} /><div className="grid gap-3 md:grid-cols-4"><MetricBlock label="Students" value="8,421" trend="+4.2%" /><MetricBlock label="Placement readiness" value="67%" trend="+8 pts" tone="violet" /><MetricBlock label="Industry aligned" value="71%" trend="+5 pts" tone="green" /><MetricBlock label="Curriculum freshness" value="62%" trend="Needs work" tone="amber" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Glass className="overflow-hidden p-0"><div className="flex items-center justify-between border-b border-white/10 p-5"><div><div className="eyebrow">Institutional signal / critical gaps</div><h2 className="mt-2 text-lg font-bold text-white">Skill gap heatmap</h2></div><select value={filter} onChange={e => setFilter(e.target.value)} className="rounded-lg border border-white/10 bg-[#121214] px-3 py-2 text-[10px] text-white/60 outline-none"><option>All departments</option><option>CSE</option><option>IT</option><option>ECE</option></select></div><div className="overflow-x-auto p-5"><div className="min-w-[650px]"><div className="grid grid-cols-[1.35fr_repeat(4,1fr)] gap-2 pb-2 text-[9px] font-mono uppercase tracking-widest text-white/30"><span>Skill / demand</span><span>CSE 2027</span><span>IT 2027</span><span>ECE 2027</span><span>Overall</span></div>{rows.map(row => <button key={row[0]} onClick={() => go("skill-intelligence")} className="grid w-full grid-cols-[1.35fr_repeat(4,1fr)] gap-2 border-t border-white/[.07] py-3 text-left hover:bg-white/[.035]"><div><div className="text-xs font-bold text-white">{row[0]}</div><div className="mt-1 text-[9px] text-white/35">Demand {row[3]}</div></div>{[row[2], "39%", "28%", row[2]].map((v, i) => <div key={i} className={`flex items-center justify-between rounded-md px-2 py-2 ${parseInt(v) < 40 ? "bg-[#b46e6e]/18" : parseInt(v) < 60 ? "bg-[#b29363]/18" : "bg-[#8eaa95]/16"}`}><span className="font-mono text-[10px] text-white/70">{v}</span><span className="h-1.5 w-1.5 rounded-full bg-current opacity-60" /></div>)}</button>)}</div></div><div className="border-t border-white/10 px-5 py-3 text-[10px] text-white/35">Click any row to inspect demand, curriculum coverage and affected cohorts.</div></Glass><Glass className="p-5"><div className="eyebrow">Readiness distribution</div><h2 className="mt-2 text-lg font-bold text-white">CSE 2027</h2><div className="mt-7 flex h-[170px] items-end gap-2 border-b border-l border-white/10 px-3 pb-0">{[22,32,42,55,62,70,77,84,91,97,104,116,128].map((h, i) => <div key={i} className={`group relative flex-1 rounded-t-sm ${i < 4 ? "bg-[#b29363]/55" : "bg-[#a58cda]/55"}`} style={{ height: h }}><span className="absolute -top-5 left-1/2 hidden -translate-x-1/2 text-[9px] text-white/50 group-hover:block">{Math.round(h / 1.4)}%</span></div>)}</div><div className="mt-4 flex justify-between text-[9px] text-white/30"><span>0%</span><span>Readiness threshold</span><span>100%</span></div><div className="mt-6 border-t border-white/10 pt-5"><div className="text-[10px] text-white/35">Students crossing threshold</div><div className="mt-2 font-mono text-2xl text-white">832 <span className="text-xs text-[#a9c9ad]">+12.4%</span></div></div></Glass></div></>; }
function MetricBlock({ label, value, trend, tone = "neutral" }: { label: string; value: string; trend: string; tone?: string }) { return <Glass className="p-5"><div className="text-[10px] uppercase tracking-[.14em] text-white/35">{label}</div><div className="mt-4 text-3xl font-bold tracking-[-.08em] text-white">{value}</div><div className={`mt-2 text-[10px] ${tone === "green" ? "text-[#a9c9ad]" : tone === "violet" ? "text-[#bda8e9]" : tone === "amber" ? "text-[#d2b37e]" : "text-white/35"}`}>{trend}</div></Glass>; }

function Curriculum() { const rows = [["ML Fundamentals", "Python", "92%", "88%", "aligned"], ["ML Fundamentals", "MLOps", "12%", "81%", "critical"], ["Cloud Computing", "Docker", "31%", "76%", "gap"], ["Data Systems", "Vector search", "8%", "68%", "critical"], ["Software Engineering", "Testing", "74%", "72%", "aligned"]]; return <><SectionTitle eyebrow="Institution / curriculum mirror" title="Curriculum Mirror" subtitle="See the path from course topics to skills and industry demand." action={<div className="flex gap-2"><Button variant="outline"><FileText size={13} /> Upload syllabus</Button><Button>Analyze curriculum <Sparkles size={13} /></Button></div>} /><Glass className="overflow-hidden p-0"><div className="grid items-center gap-5 border-b border-white/10 p-5 md:grid-cols-[.9fr_1.1fr]"><div><div className="eyebrow">Syllabus analysis / B.Tech CSE</div><h2 className="mt-2 text-xl font-bold text-white">Curriculum alignment matrix</h2><p className="mt-2 text-xs leading-5 text-white/40">14 courses, 82 topics, 46 mapped skills.</p></div><div className="flex items-center gap-3"><div className="h-2 flex-1 rounded-full bg-white/10"><div className="h-full w-[62%] rounded-full bg-[#a58cda]" /></div><span className="font-mono text-xs text-white">62%</span><span className="text-[10px] text-white/35">freshness</span></div></div><div className="overflow-x-auto p-5"><table className="w-full min-w-[700px] border-collapse"><thead><tr className="text-left text-[9px] font-mono uppercase tracking-widest text-white/30"><th className="pb-3">Course</th><th className="pb-3">Skill</th><th className="pb-3">Coverage</th><th className="pb-3">Industry demand</th><th className="pb-3">Signal</th><th className="pb-3">Action</th></tr></thead><tbody>{rows.map(r => <tr key={r[1]} className="border-t border-white/[.07] text-xs"><td className="py-4 text-white/65">{r[0]}</td><td className="py-4 font-bold text-white">{r[1]}</td><td className="py-4 font-mono text-white/65">{r[2]}</td><td className="py-4 font-mono text-[#c3afe9]">{r[3]}</td><td className="py-4"><Status tone={r[4] === "aligned" ? "green" : r[4] === "gap" ? "amber" : "red"}>{r[4]}</Status></td><td className="py-4"><button className="text-white/40 hover:text-white"><ArrowRight size={14} /></button></td></tr>)}</tbody></table></div></Glass><div className="mt-5 grid gap-5 md:grid-cols-3"><Insight title="Critical gaps" value="3" text="MLOps, Vector search, Cloud deployment" tone="red" /><Insight title="Industry-aligned" value="28" text="Skills currently covered by curriculum" tone="green" /><Insight title="Recommended update" value="6 weeks" text="Add a production systems module" tone="violet" /></div></>; }
function Insight({ title, value, text, tone }: { title: string; value: string; text: string; tone: string }) { return <Glass className="p-5"><div className="eyebrow">{title}</div><div className={`mt-3 font-mono text-3xl ${tone === "red" ? "text-[#d19a9a]" : tone === "green" ? "text-[#a9c9ad]" : "text-[#c0aae8]"}`}>{value}</div><div className="mt-2 text-xs leading-5 text-white/40">{text}</div></Glass>; }

function Simulator() { const [students, setStudents] = useState(300); const [mentors, setMentors] = useState(12); const [weeks, setWeeks] = useState(6); const readiness = Math.min(86, 48 + Math.round((students / 300) * 15) + Math.round((mentors / 12) * 7) + (weeks - 6) * 2); return <><SectionTitle eyebrow="Institution / intervention planning" title="What-If Simulator" subtitle="Simulate the solution. Don't just measure the gap." action={<Status tone="amber">Projected · not a guarantee</Status>} /><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Glass className="p-6"><div className="eyebrow">Intervention builder</div><h2 className="mt-3 text-xl font-bold text-white">6-week Cloud Bridge Program</h2><p className="mt-2 text-xs leading-5 text-white/40">Close the Docker, AWS and MLOps gap for the cohort most exposed to AI/ML roles.</p><div className="mt-8 space-y-6">{[["Target cohort", students, setStudents, 100, 500, "students"], ["Mentors", mentors, setMentors, 4, 30, "industry mentors"], ["Program duration", weeks, setWeeks, 4, 12, "weeks"]].map(([label, value, setter, min, max, suffix]) => <div key={label as string}><div className="mb-2 flex justify-between text-[10px] text-white/45"><span>{label as string}</span><span className="font-mono text-white">{value as number} <span className="text-white/35">{suffix as string}</span></span></div><input type="range" min={min as number} max={max as number} value={value as number} onChange={e => (setter as (v: number) => void)(Number(e.target.value))} className="w-full accent-[#a58cda]" /></div>)}</div><div className="mt-8 flex flex-wrap gap-2"><Status tone="violet">Docker</Status><Status tone="violet">AWS</Status><Status tone="violet">MLOps</Status></div><Button className="mt-8 w-full">Generate intervention plan <Sparkles size={13} /></Button></Glass><Glass className="p-6"><div className="flex items-center justify-between"><div><div className="eyebrow">Model output / simulation 004</div><h2 className="mt-2 text-xl font-bold text-white">Baseline vs projected</h2></div><span className="rounded-md bg-[#b29363]/15 px-2 py-1 text-[9px] font-mono text-[#d5b77e]">PROJECTED</span></div><div className="mt-8 grid gap-3 sm:grid-cols-2">{[["Readiness", "48%", `${readiness}%`, "#a58cda"], ["Eligible students", "244", `${Math.round(students * readiness / 100)}`, "#8eaa95"], ["Opportunity matches", "167", `${Math.round(167 + (readiness - 48) * 7.3)}`, "#a58cda"], ["Verified skills", "1.4 avg", `${(1.4 + (readiness - 48) / 10).toFixed(1)} avg`, "#8eaa95"]].map(([label, before, after, color]) => <div key={label} className="rounded-lg border border-white/10 bg-white/[.025] p-4"><div className="text-[10px] text-white/35">{label}</div><div className="mt-4 flex items-end gap-3"><span className="font-mono text-xl text-white/35 line-through">{before}</span><ArrowRight size={14} className="mb-1 text-white/25" /><span className="font-mono text-2xl" style={{ color }}>{after}</span></div><div className="mt-3 h-1 rounded bg-white/10"><div className="h-full rounded" style={{ width: `${Math.min(100, parseFloat(after as string) || 50)}%`, background: color }} /></div></div>)}</div><div className="mt-7 border-t border-white/10 pt-5"><div className="eyebrow">Projected trajectory</div><div className="mt-5 flex h-28 items-end gap-2">{[48, 52, 55, 61, 64, 68, readiness].map((v, i) => <div key={i} className="group relative flex-1 rounded-t bg-[#a58cda]/60 transition-all" style={{ height: `${v}%` }}><span className="absolute -top-5 left-1/2 hidden -translate-x-1/2 text-[9px] text-white/55 group-hover:block">{v}%</span></div>)}</div><div className="mt-5 text-[10px] leading-5 text-white/35">Model estimate based on historical intervention patterns. Outcomes vary by attendance, mentor quality and project completion.</div></div></Glass></div></>; }

function IndustryTalent() { const [segment, setSegment] = useState("Near ready"); const candidates = [["Aanya Sharma", "91%", "Python · ML · SQL", "CSE / 2027", "3 verified projects"], ["Rohan Mehta", "86%", "Python · Cloud · Docker", "IT / 2027", "5 verified projects"], ["Meera Iyer", "78%", "ML · SQL · Statistics", "CSE / 2026", "2 verified projects"], ["Arjun Nair", "63%", "Python · ML", "ECE / 2027", "1 verified project"]]; return <><SectionTitle eyebrow="Industry / talent intelligence" title="Find potential, not keywords." subtitle="Nova Systems · search the skill graph across verified evidence." action={<Button>Post opportunity <Plus size={13} /></Button>} /><Glass className="p-5"><div className="grid gap-3 md:grid-cols-[1.2fr_1fr_1fr_auto]"><div className="flex items-center gap-2 rounded-lg border border-white/10 bg-white/[.035] px-3 py-2.5"><Search size={14} className="text-white/35" /><span className="text-xs text-white/65">AI / ML candidates</span></div><div className="rounded-lg border border-white/10 bg-white/[.035] px-3 py-2.5 text-xs text-white/55">Python &gt; 75 · ML &gt; 70</div><div className="rounded-lg border border-white/10 bg-white/[.035] px-3 py-2.5 text-xs text-white/55">All institutions <ChevronDown size={13} className="ml-2 inline text-white/30" /></div><Button>Apply filters</Button></div></Glass><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_.7fr]"><Glass className="overflow-hidden p-0"><div className="flex items-center justify-between border-b border-white/10 p-5"><div className="flex gap-1 rounded-lg border border-white/10 p-1">{["Ready now", "Near ready", "Developing"].map(s => <button key={s} onClick={() => setSegment(s)} className={`rounded-md px-3 py-2 text-[10px] ${segment === s ? "bg-white/10 text-white" : "text-white/35"}`}>{s}</button>)}</div><span className="font-mono text-[10px] text-white/35">1,284 candidates</span></div><div className="divide-y divide-white/[.07]">{candidates.map((c, i) => <button key={c[0]} className={`flex w-full items-center gap-4 p-5 text-left transition hover:bg-white/[.045] ${segment === "Ready now" && i > 1 ? "hidden" : segment === "Developing" && i < 2 ? "hidden" : ""}`}><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-white/10 bg-white/[.06] text-[10px] font-bold text-white/70">{c[0].split(" ").map(n => n[0]).join("")}</div><div className="min-w-0 flex-1"><div className="text-xs font-bold text-white">{c[0]}</div><div className="mt-1 text-[10px] text-white/35">{c[3]} · {c[4]}</div></div><div className="hidden text-right sm:block"><div className="text-[9px] text-white/30">Skill compatibility</div><div className="mt-1 font-mono text-sm text-[#a9c9ad]">{c[1]}</div></div><div className="hidden max-w-[150px] text-right md:block"><div className="text-[9px] text-white/30">Verified skills</div><div className="mt-1 truncate text-[10px] text-white/55">{c[2]}</div></div><ChevronRight size={15} className="text-white/25" /></button>)}</div></Glass><Glass className="p-5"><div className="eyebrow">Talent pool composition</div><div className="mt-6 space-y-5">{[["AI / ML", "1,284", "#a58cda"], ["Cloud", "943", "#8eaa95"], ["Cybersecurity", "621", "#b29363"], ["Data engineering", "512", "#8a8791"]].map(([a,b,c]) => <div key={a}><div className="flex justify-between text-xs"><span className="text-white/65">{a}</span><span className="font-mono text-white">{b}</span></div><div className="mt-2 h-1.5 rounded bg-white/[.08]"><div className="h-full rounded" style={{ width: `${Math.min(100, Number(b) / 14)}%`, background: c }} /></div></div>)}</div><div className="mt-7 border-t border-white/10 pt-5"><div className="text-[10px] text-white/35">Best immediate match</div><div className="mt-2 text-sm font-bold text-white">Aanya Sharma</div><div className="mt-1 text-xs text-white/40">91% compatibility · 3 verified projects</div><Button variant="outline" className="mt-4 w-full">Open Skill DNA <ArrowRight size={13} /></Button></div></Glass></div></>; }

function FacultyPassport() { return <><SectionTitle eyebrow="Faculty / industry passport" title="Stay close to the real world." subtitle="Your industry exposure becomes part of the institution's skill intelligence." action={<Button>Add experience <Plus size={13} /></Button>} /><div className="grid gap-5 xl:grid-cols-[.75fr_1.25fr]"><Glass className="p-6"><div className="flex items-center gap-4"><div className="flex h-14 w-14 items-center justify-center rounded-xl bg-[#d5c6ed] text-lg font-bold text-[#17121e]">KR</div><div><div className="text-lg font-bold text-white">Dr. Kavita Rao</div><div className="mt-1 text-xs text-white/40">Associate Professor · Computer Science</div></div></div><div className="mt-8"><div className="flex items-end justify-between"><div><div className="eyebrow">Faculty industry exposure</div><div className="mt-2 font-mono text-4xl text-white">47%</div></div><span className="font-mono text-xs text-[#c2aae8]">+8% this year</span></div><div className="mt-4"><Progress value={47} /></div></div><div className="mt-8 grid grid-cols-2 gap-3">{[["Industry projects", "4"], ["Mentored students", "38"], ["Research links", "6"], ["FDP completed", "3"]].map(([a,b]) => <div key={a} className="rounded-lg border border-white/10 bg-white/[.03] p-3"><div className="text-[10px] text-white/35">{a}</div><div className="mt-2 font-mono text-lg text-white">{b}</div></div>)}</div></Glass><Glass className="p-6"><div className="eyebrow">Recommended next steps</div><h2 className="mt-2 text-xl font-bold text-white">Build your industry passport</h2><div className="mt-6 space-y-3">{[["Industry immersion", "2-week applied program with Nova Systems", "+12 exposure", "violet"], ["Mentor a live project", "Guide a student team through RAG deployment", "+8 exposure", "green"], ["Apply for FDP", "Production ML systems · 18 seats remaining", "deadline in 9d", "amber"]].map(([a,b,c,t]) => <div key={a} className="flex items-center gap-4 rounded-lg border border-white/10 bg-white/[.025] p-4"><div className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${t === "green" ? "bg-[#8eaa95]/15 text-[#a9c9ad]" : t === "amber" ? "bg-[#b29363]/15 text-[#d5b67d]" : "bg-[#a58cda]/15 text-[#c2ace8]"}`}><GraduationCap size={17} /></div><div className="min-w-0 flex-1"><div className="text-xs font-bold text-white">{a}</div><div className="mt-1 text-[10px] text-white/40">{b}</div></div><span className="hidden text-[9px] font-mono text-white/40 sm:block">{c}</span><ChevronRight size={14} className="text-white/25" /></div>)}</div></Glass></div></>; }

function PlaceholderView({ role, page }: { role: Role; page: string }) { return <><SectionTitle eyebrow={`${roleMeta[role].label} / workspace`} title={page.replace(/-/g, " ")} subtitle="This workspace is connected to the same ShikshaSetu intelligence graph." /><Glass className="flex min-h-[360px] items-center justify-center p-10 text-center"><div><Network size={30} className="mx-auto text-[#a58cda]" /><h2 className="mt-5 text-xl font-bold capitalize text-white">{page.replace(/-/g, " ")} intelligence</h2><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-white/40">The next signal is being mapped here. Continue exploring the command center, skill graph and connected evidence.</p><Button className="mt-6">Explore connected graph <ArrowRight size={13} /></Button></div></Glass></>; }

export default function Workspace() { const location = useLocation(); const navigate = useNavigate(); const parts = location.pathname.split("/").filter(Boolean); const role = (parts[1] as Role) || "student"; const page = parts[2] || navByRole[role]?.[0].slug || "overview"; const [command, setCommand] = useState(false); const go = (p: string) => navigate(`/app/${role}/${p}`); const content = role === "student" && page === "overview" ? <StudentOverview go={go} /> : role === "student" && page === "skill-dna" ? <SkillDNA /> : role === "student" && page === "roadmap" ? <Roadmap /> : role === "student" && page === "career-simulator" ? <CareerSimulator /> : role === "institution" && page === "command-center" ? <InstitutionCommand go={go} /> : role === "institution" && page === "curriculum" ? <Curriculum /> : role === "institution" && page === "simulator" ? <Simulator /> : role === "industry" && page === "talent" ? <IndustryTalent /> : role === "faculty" && page === "passport" ? <FacultyPassport /> : <PlaceholderView role={role} page={page} />; return <><WorkspaceShell role={role} page={page} onCommand={() => setCommand(true)}>{content}</WorkspaceShell>{command && <CommandPalette onClose={() => setCommand(false)} />}</>; }
